package com.srent.ekyc;
import com.srent.common.ApiException; import com.srent.config.AppProperties; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.http.*; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient;
@Component @ConditionalOnProperty(name="app.providers.ekyc-mode",havingValue="external")
public class ExternalEkycProvider implements EkycProvider {private final AppProperties p;private final RestClient client=RestClient.create();public ExternalEkycProvider(AppProperties p){this.p=p;}public Result process(Input i){var x=p.getProviders();if(x.getEkycEndpoint()==null||x.getEkycEndpoint().isBlank()||x.getEkycApiKey()==null||x.getEkycApiKey().isBlank())throw new ApiException(HttpStatus.SERVICE_UNAVAILABLE,"EKYC_NOT_CONFIGURED","External eKYC chưa có endpoint/API key hợp lệ");try{return client.post().uri(x.getEkycEndpoint()).header("Authorization","Bearer "+x.getEkycApiKey()).body(i).retrieve().body(Result.class);}catch(Exception e){throw new ApiException(HttpStatus.BAD_GATEWAY,"EKYC_PROVIDER_ERROR","Nhà cung cấp eKYC không phản hồi hợp lệ");}}public String name(){return "EXTERNAL_EKYC";}public boolean simulated(){return false;}}
